style.extraCss:
/* ===== 亮色 ===== */
[class*="MainContentTopFade"], [class*="bg-gradient-to-"] { background-image: none !important; }
[class*="scroll-fade-mask"]:not(.vertical-scroll-fade-mask), [class*="fade-mask"]:not(.vertical-scroll-fade-mask) { -webkit-mask-image: none !important; mask-image: none !important; }
[class*="MainContentSurface"], [class*="ContentSurface"], [class*="_ApplicationMenuTopBar_"] { background-color: transparent !important; }
.bg-user-message { background-color: color-mix(in srgb, #ffffff 80%, transparent) !important; border: 1.5px solid #cfb35b !important; border-radius: 22px 22px 0 22px !important; box-shadow: 0 4px 14px rgba(0, 0, 0, 0.16) !important; }
.bg-user-message [class*="_MarkdownRoot"] { background-color: transparent !important; border: 0 !important; border-radius: 0 !important; padding: 0 !important; box-shadow: none !important; }
[class*="_MarkdownRoot"] { background-color: color-mix(in srgb, #ffffff 80%, transparent) !important; border: 1.5px solid #cfb35b !important; border-radius: 22px 22px 22px 0 !important; padding: 12px 16px !important; box-shadow: 0 4px 14px rgba(0, 0, 0, 0.16) !important; }
[class*="backdrop-blur"] { backdrop-filter: blur(24px) !important; }
[class*="bg-surface/90"], [class*="bg-surface-elevated/90"], [class*="bg-surface-elevated-secondary/90"] { background-color: color-mix(in srgb, #ffffff 20%, transparent) !important; box-shadow: 0 16px 38px rgba(0, 0, 0, 0.20) !important; }
[class*="bg-surface"]:not([class*="elevated"]) { background-color: color-mix(in srgb, #ffffff 20%, transparent) !important; backdrop-filter: blur(24px) !important; box-shadow: 0 16px 38px rgba(0, 0, 0, 0.20) !important; }
[class*="_ApplicationMenuTopBar_"], [class*="_ApplicationMenuTopBar_"] *, [class*="text-tertiary"], .sidebar-item, [class*="group/nav-section-title"] { color: rgb(24, 28, 38) !important; }

/* ===== 深色模式（Codex 以 html.electron-dark 标识；背景图已在模板里切换为暗图）===== */
html.electron-dark .bg-user-message { background-color: color-mix(in srgb, #1b1d24 84%, transparent) !important; }
html.electron-dark [class*="_MarkdownRoot"] { background-color: color-mix(in srgb, #1b1d24 84%, transparent) !important; }
html.electron-dark [class*="backdrop-blur"] { backdrop-filter: blur(24px) !important; }
html.electron-dark [class*="bg-surface/90"], html.electron-dark [class*="bg-surface-elevated/90"], html.electron-dark [class*="bg-surface-elevated-secondary/90"] { background-color: color-mix(in srgb, #1b1d24 20%, transparent) !important; }
html.electron-dark [class*="bg-surface"]:not([class*="elevated"]) { background-color: color-mix(in srgb, #1b1d24 20%, transparent) !important; }
html.electron-dark [class*="_ApplicationMenuTopBar_"], html.electron-dark [class*="_ApplicationMenuTopBar_"] *, html.electron-dark [class*="text-tertiary"], html.electron-dark .sidebar-item { color: rgb(232, 236, 244) !important; }
